// Meta connects a webhook with a GET: it must get its own hub.challenge back, and only
// if hub.verify_token matches the club's. The token comes from wa_webhook_config; the
// staging build also bakes the configured token in, so the handshake works before the
// database has been set up.
const H=this.helpers;
const VERIFY_FALLBACK='';
try{
const SUPA='__SUPABASE_URL__',SR='__SUPABASE_SERVICE_KEY__';
const sH={apikey:SR,Authorization:'Bearer '+SR};
const q=($input.first().json||{}).query||{};
let token=null;
try{
  const tr=await H.httpRequest({method:'GET',url:SUPA+'/rest/v1/tenants?slug=eq.shakti&select=id',headers:sH,json:true});
  const t=Array.isArray(tr)?tr[0]:null;
  if(t){ const cr=await H.httpRequest({method:'GET',url:SUPA+'/rest/v1/wa_webhook_config?tenant_id=eq.'+t.id+'&select=verify_token',headers:sH,json:true}); token=(Array.isArray(cr)&&cr[0]&&cr[0].verify_token)||null; }
}catch(e){}
if(!token && VERIFY_FALLBACK) token=VERIFY_FALLBACK;
const ok=q['hub.mode']==='subscribe' && !!token && String(q['hub.verify_token']||'')===String(token);
return [{json:{ok,challenge:ok?String(q['hub.challenge']||''):'forbidden',code:ok?200:403}}];
}catch(e){ return [{json:{ok:false,challenge:'error',code:500}}]; }

// Records WhatsApp status events (sent / delivered / read / failed) sent by Meta's webhook,
// and logs replies that arrive here directly. The signature is checked against the app secret
// with a self-contained SHA-256, so it works in any n8n sandbox. The 200 reply goes out before
// this runs (the webhook node responds immediately), which is what Meta requires.
const H=this.helpers;
try{
const SUPA='__SUPABASE_URL__',SR='__SUPABASE_SERVICE_KEY__',CONFIRM='__CONFIRM_TOKEN__';
const sH={apikey:SR,Authorization:'Bearer '+SR};
const item=$input.first(); const q=item.json||{};
const headers=q.headers||{};
/* the exact bytes Meta signed: n8n's binary reader works whether binary data is kept in memory or on disk */
let raw=null;
try{ if(item.binary&&item.binary.data&&typeof H.getBinaryDataBuffer==='function'){ const buf=await H.getBinaryDataBuffer(0,'data'); if(buf&&buf.length) raw=new Uint8Array(buf); } }catch(e){}
if(!raw){ try{ const bd=item.binary&&item.binary.data; if(bd&&bd.data&&!bd.id) raw=new Uint8Array(Buffer.from(bd.data,'base64')); }catch(e){} }
let body=(q.body&&typeof q.body==='object'&&Object.keys(q.body).length)?q.body:null;
if(!body&&raw){ try{ body=JSON.parse(Buffer.from(raw).toString('utf8')); }catch(e){} }
body=body||{};
const hdr=(n)=>{ n=n.toLowerCase(); for(const k in headers){ if(String(k).toLowerCase()===n) return String(headers[k]||''); } return ''; };

// ---- SHA-256 / HMAC without any module ----
const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
function sha256Bytes(bytes){
  let Hh=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l=bytes.length, padLen=((l+9+63)>>6)<<6; const p=new Uint8Array(padLen); p.set(bytes); p[l]=0x80;
  const bits=l*8, hi=Math.floor(bits/4294967296), lo=bits>>>0;
  p[padLen-8]=(hi>>>24)&255; p[padLen-7]=(hi>>>16)&255; p[padLen-6]=(hi>>>8)&255; p[padLen-5]=hi&255;
  p[padLen-4]=(lo>>>24)&255; p[padLen-3]=(lo>>>16)&255; p[padLen-2]=(lo>>>8)&255; p[padLen-1]=lo&255;
  const w=new Array(64); const rotr=(x,n)=>(x>>>n)|(x<<(32-n));
  for(let i=0;i<padLen;i+=64){
    for(let t=0;t<16;t++) w[t]=(p[i+t*4]<<24)|(p[i+t*4+1]<<16)|(p[i+t*4+2]<<8)|p[i+t*4+3];
    for(let t=16;t<64;t++){ const s0=rotr(w[t-15],7)^rotr(w[t-15],18)^(w[t-15]>>>3); const s1=rotr(w[t-2],17)^rotr(w[t-2],19)^(w[t-2]>>>10); w[t]=(w[t-16]+s0+w[t-7]+s1)|0; }
    let a=Hh[0],b=Hh[1],c=Hh[2],d=Hh[3],e=Hh[4],f=Hh[5],g=Hh[6],h=Hh[7];
    for(let t=0;t<64;t++){ const S1=rotr(e,6)^rotr(e,11)^rotr(e,25), ch=(e&f)^(~e&g), t1=(h+S1+ch+K[t]+w[t])|0, S0=rotr(a,2)^rotr(a,13)^rotr(a,22), mj=(a&b)^(a&c)^(b&c), t2=(S0+mj)|0; h=g;g=f;f=e;e=(d+t1)|0;d=c;c=b;b=a;a=(t1+t2)|0; }
    Hh=[(Hh[0]+a)|0,(Hh[1]+b)|0,(Hh[2]+c)|0,(Hh[3]+d)|0,(Hh[4]+e)|0,(Hh[5]+f)|0,(Hh[6]+g)|0,(Hh[7]+h)|0];
  }
  const out=new Uint8Array(32); Hh.forEach((x,i)=>{ out[i*4]=(x>>>24)&255; out[i*4+1]=(x>>>16)&255; out[i*4+2]=(x>>>8)&255; out[i*4+3]=x&255; });
  return out;
}
const hex=(u)=>Array.from(u,x=>x.toString(16).padStart(2,'0')).join('');
function hmacHex(secret,msg){
  let key=new Uint8Array(Buffer.from(String(secret),'utf8')); if(key.length>64) key=sha256Bytes(key);
  const k=new Uint8Array(64); k.set(key);
  const inner=new Uint8Array(64+msg.length), outer=new Uint8Array(96);
  for(let i=0;i<64;i++){ inner[i]=k[i]^0x36; outer[i]=k[i]^0x5c; }
  inner.set(msg,64); outer.set(sha256Bytes(inner),64);
  return hex(sha256Bytes(outer));
}
const sameStr=(a,b)=>{ a=String(a||''); b=String(b||''); let r=a.length^b.length; for(let i=0;i<Math.max(a.length,b.length);i++) r|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0); return r===0; };

// ---- tenant + webhook secrets (service role only) ----
const tr=await H.httpRequest({method:'GET',url:SUPA+'/rest/v1/tenants?slug=eq.shakti&select=id',headers:sH,json:true});
const t=Array.isArray(tr)?tr[0]:null; if(!t) return [{json:{ok:false,error:'tenant not found'}}];
let cfg={}, note='';
try{ const cr=await H.httpRequest({method:'GET',url:SUPA+'/rest/v1/wa_webhook_config?tenant_id=eq.'+t.id+'&select=app_secret,verify_token',headers:sH,json:true}); cfg=(Array.isArray(cr)&&cr[0])||{}; }
catch(e){ note='wa_webhook_config not found: run sql/wa_message_status.sql. '; }

// ---- who is calling: Meta directly, or the club's inbound workflow forwarding Meta's event. Both must carry
//      Meta's own signature (a forward passes on the exact body bytes and the X-Hub-Signature-256 header).
//      The x-confirm header only marks a forward, whose messages are not stored again here (the inbound
//      workflow stores them); it never skips the signature check ----
const forwarded = CONFIRM && sameStr(hdr('x-confirm'),CONFIRM);
if(!cfg.app_secret) return [{json:{ok:false,error:note+'no app secret stored in wa_webhook_config: events are refused and nothing is recorded until it is stored'}}];
if(!raw) return [{json:{ok:false,error:'raw body unavailable, cannot verify the signature (enable "Raw Body" on the webhook node)'}}];
if(!sameStr(hdr('x-hub-signature-256'),'sha256='+hmacHex(cfg.app_secret,raw))) return [{json:{ok:false,error:'signature mismatch: event ignored'}}];
const verified=true;

// ---- apply every status event; log replies that reach us directly ----
let applied=0, ignored=0, replies=0; const errs=[];
const apply=async(p)=>{
  const r=await H.httpRequest({method:'POST',url:SUPA+'/rest/v1/rpc/wa_status_apply',headers:{...sH,'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(p),returnFullResponse:true,ignoreHttpStatusErrors:true});
  if(r.statusCode<300) applied++; else { ignored++; if(errs.length<3) errs.push(String(typeof r.body==='string'?r.body:JSON.stringify(r.body)).slice(0,160)); }
};
for(const entry of (body.entry||[])){
  for(const change of (entry.changes||[])){
    if(change.field!=='messages'||!change.value) continue;
    const v=change.value;
    for(const st of (v.statuses||[])){
      if(!st||!st.id||!st.status) continue;
      const e=(st.errors&&st.errors[0])||null;
      await apply({p_wamid:String(st.id),p_tenant:t.id,p_status:String(st.status).toLowerCase(),
        p_at:st.timestamp?new Date(Number(st.timestamp)*1000).toISOString():new Date().toISOString(),
        p_phone:st.recipient_id?String(st.recipient_id).replace(/[^0-9]/g,''):null,
        p_code:e&&e.code!=null?Number(e.code):null, p_title:e?(e.title||null):null,
        p_detail:e?((e.error_data&&e.error_data.details)||e.message||null):null,
        p_conv:(st.conversation&&st.conversation.id)||null,
        p_category:(st.pricing&&st.pricing.category)||null,
        p_billable:(st.pricing&&typeof st.pricing.billable==='boolean')?st.pricing.billable:null,
        p_create:false});
    }
    if(!forwarded){
      for(const msg of (v.messages||[])){
        if(!msg||!msg.from) continue;
        const text=(msg.text&&msg.text.body)||(msg.button&&msg.button.text)||(msg.interactive&&((msg.interactive.button_reply&&msg.interactive.button_reply.title)||(msg.interactive.list_reply&&msg.interactive.list_reply.title)))||('['+(msg.type||'message')+']');
        try{
          const row={tenant_id:t.id,phone:String(msg.from).replace(/[^0-9]/g,''),direction:'in',body:String(text).slice(0,4000),msg_type:msg.type||'text',intent:'reply'};
          const post=(x)=>H.httpRequest({method:'POST',url:SUPA+'/rest/v1/wa_messages',headers:{...sH,'Content-Type':'application/json',Prefer:'return=minimal'},
            body:JSON.stringify(x),returnFullResponse:true,ignoreHttpStatusErrors:true});
          let r=await post(msg.id?Object.assign({wamid:String(msg.id)},row):row);
          /* 409: already stored (Meta repeats deliveries). Any other refusal: a database without the wamid column yet */
          if(r.statusCode>=400&&r.statusCode!==409&&msg.id) r=await post(row);
          if(r.statusCode<300) replies++;
        }catch(e){}
      }
    }
  }
}
return [{json:{ok:true,verified,forwarded,applied,ignored,replies,note:note||undefined,errors:errs.length?errs:undefined}}];
}catch(e){ return [{json:{ok:false,error:String((e&&e.message)||e)}}]; }
